# Writes the provenance register from the download manifest, and checks each asset against what the pipeline scripts actually read.
# Usage: python write_provenance.py <out.md>
import json, os, sys

OUT = sys.argv[1]
HERE = os.path.dirname(os.path.abspath(__file__))
m = json.load(open(os.path.expanduser("~/portfolio-assets/source/MANIFEST-vael.json"), encoding="utf8"))
code = {f: open(os.path.join(HERE, f), encoding="utf8").read() for f in ("process_nature.py", "paint_textures.py", "build_town.py")}
HOW = {"process_nature.py": "Leaves reduced to painted clump cards, or mesh decimated with crevice shading; origin moved to its base", "paint_textures.py": "Repainted by Kuwahara filter, regraded; height stored in alpha; downscaled to 1024", "build_town.py": "Pieces fitted along the hill, tinted, occlusion baked in Cycles"}
rows = []; unused = []
for e in m:
    short = e["id"].removeprefix("PH-")
    used = [f for f, t in code.items() if f'"{short}"' in t or short in t]
    if used:
        rows.append(f"| {e['name']} | {', '.join(e.get('creators', [])) or 'not recorded'} | [{short}]({e['page']}) | {e['licence']} | {e['downloaded'][:10]} | {'; '.join(HOW[f] for f in used)} |")
    else:
        unused.append(f"- {e['name']} ([{short}]({e['page']})), {e['licence']}")
with open(OUT, "w", encoding="utf8") as f:
    f.write("# Asset provenance register: Vael\n\nGenerated by `pipeline/vael/write_provenance.py` from `~/portfolio-assets/source/MANIFEST-vael.json`, which also holds each file's URL and SHA-256. Raw sources stay in `~/portfolio-assets/source/`, outside the repo.\n\n")
    f.write("## In the build\n\n| Asset | Creator | Source | Licence | Downloaded | Modifications |\n|---|---|---|---|---|---|\n" + "\n".join(rows) + "\n\n")
    f.write("## Downloaded, not in the build\n\n" + ("\n".join(unused) or "None.") + "\n\n")
    f.write("## Made for this project\n\n| Item | How |\n|---|---|\n| Far ranges (`vael_mountains.webp`) | Own heightfield (`make_height.py`), rendered in Cycles, repainted (`paint_backdrop.py`) |\n| Sky (`vael_sky.webp`) | Own volumetric clouds rendered in Cycles, repainted |\n| Foliage atlas (`vael_foliage.webp`) | Rasterised from the CC0 plant and tree geometry above (`paint_clumps.py`) |\n| Gatehouse, keep, hall, chapel, houses, dry-stone walls | Original geometry (`build_town.py`) |\n| Land, road, Red Line, banners, smoke | Original code (`src/vael-geometry.js`, `src/shaders-texpaint.js`) |\n\n")
    f.write("No AI-generated imagery, purchased asset, login-gated download or reference frame is used. CC0 requires no credit; crediting Poly Haven on the finished site would still be a courtesy.\n")
print(len(rows), "in build;", len(unused), "not in build")
